files.nginx.conf.example:
# Include inside nginx's http {} block. Replace example.invalid and certificate paths.
# This is the direct-to-origin example; CDN real-IP trust requires separate configuration.
# Run `nginx -t` on the target host before reload. No certificate provisioning is performed.
limit_req_zone $binary_remote_addr zone=ultra_client:10m rate=1r/s;
limit_req_zone $server_name zone=ultra_global:1m rate=10r/s;
limit_conn_zone $binary_remote_addr zone=ultra_connections:10m;
log_format ultra_minimal '{"status":$status,"request_id":"$request_id"}';

server {
    listen 80 default_server;
    server_name _;
    return 444;
}
server {
    listen 80;
    server_name example.invalid;
    return 308 https://example.invalid$request_uri;
}
server {
    listen 443 ssl default_server;
    server_name _;
    ssl_reject_handshake on;
    return 444;
}
server {
    listen 443 ssl;
    server_name example.invalid;
    ssl_certificate /etc/letsencrypt/live/example.invalid/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.invalid/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    server_tokens off;

    client_max_body_size 16k;
    client_body_buffer_size 16k;
    client_header_timeout 5s;
    client_body_timeout 5s;
    send_timeout 10s;
    keepalive_timeout 10s;
    large_client_header_buffers 2 4k;
    limit_req zone=ultra_client burst=5 nodelay;
    limit_req zone=ultra_global burst=20 nodelay;
    limit_req_status 429;
    limit_conn ultra_connections 10;
    access_log /var/log/nginx/ultra_access.log ultra_minimal;
    # Nginx error logs can contain client IPs and URLs; restrict and rotate them.
    error_log /var/log/nginx/ultra_error.log warn;

    add_header Strict-Transport-Security "max-age=31536000" always;
    add_header X-Content-Type-Options nosniff always;
    add_header X-Frame-Options DENY always;
    add_header Referrer-Policy no-referrer always;
    add_header Permissions-Policy "camera=(), microphone=(), geolocation=(), payment=()" always;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; frame-src 'none'; frame-ancestors 'none'; object-src 'none'; base-uri 'none'; form-action 'self'" always;

    location ~ (^|/)\. { return 404; }

    location / {
        proxy_pass http://127.0.0.1:8000;
        proxy_http_version 1.1;
        proxy_request_buffering on;
        proxy_buffering on;
        proxy_next_upstream off;
        proxy_connect_timeout 2s;
        proxy_read_timeout 15s;
        proxy_send_timeout 10s;
        proxy_set_header Host example.invalid;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For "";
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-Forwarded-Protocol "";
        proxy_set_header X-Forwarded-Ssl "";
        proxy_set_header Forwarded "";
        proxy_set_header Connection "";
        proxy_set_header Upgrade "";
        proxy_set_header SCRIPT_NAME "";
        proxy_set_header PATH_INFO "";
        proxy_set_header REMOTE_USER "";
        proxy_hide_header X-Powered-By;
        # Defined once above, also on Nginx-generated errors.
        proxy_hide_header Strict-Transport-Security;
        proxy_hide_header X-Content-Type-Options;
        proxy_hide_header X-Frame-Options;
        proxy_hide_header Referrer-Policy;
        proxy_hide_header Permissions-Policy;
        proxy_hide_header Content-Security-Policy;
    }
}

files.windows-defender.ps1:
#Requires -Version 5.1
#Requires -RunAsAdministrator
<#
Status is the default. Scan updates signatures and requests a full Defender scan.
No exclusions are added and no protection is disabled. Remediation is governed
by the existing Microsoft Defender policy, not a custom deletion algorithm.
#>
[CmdletBinding()]
param([ValidateSet('Status', 'Scan')][string]$Action = 'Status')

$ErrorActionPreference = 'Stop'
try {
    if (-not (Get-Command Get-MpComputerStatus -ErrorAction SilentlyContinue)) {
        throw 'Microsoft Defender PowerShell module is not available.'
    }
    $status = Get-MpComputerStatus
    $status | Select-Object AMServiceEnabled, AntivirusEnabled, RealTimeProtectionEnabled,
        AntivirusSignatureLastUpdated, FullScanStartTime, FullScanEndTime
    if (-not $status.AntivirusEnabled -or -not $status.RealTimeProtectionEnabled) {
        Write-Warning 'Defender is not providing the expected active protection. Check Windows Security or the installed security product.'
        exit 2
    }
    if ($Action -eq 'Scan') {
        Update-MpSignature
        Start-MpScan -ScanType FullScan
        Write-Output 'Scan command returned. Review scan completion and Protection History in Windows Security. This is not a malware-free guarantee.'
        Get-MpComputerStatus | Select-Object FullScanStartTime, FullScanEndTime, AntivirusSignatureLastUpdated
    }
} catch {
    Write-Error 'Defender status/update/scan did not complete successfully. Check Windows Security and administrator permissions.'
    exit 2
}

