@echo off
setlocal
chcp 65001 >nul
set PYTHONUTF8=1
cd /d "%~dp0.."
where py >nul 2>nul
if errorlevel 1 (
  echo Install supported Python 3.12 or newer from python.org first.
  pause
  exit /b 2
)
if not exist policy.json if not exist .guard-state (
  py -3 -m ultra_guard init
  if errorlevel 1 (
    pause
    exit /b 2
  )
)
py -3 -m ultra_guard demo
if errorlevel 1 pause
